  "code": "## 初始化函数，设定要操作的股票、基准等等\ndef initialize(context):\n    # 设定沪深300作为基准\n    set_benchmark('000300.XSHG')\n    # True为开启动态复权模式，使用真实价格交易\n    set_option('use_real_price', True) \n    # 设定成交量比例\n    set_option('order_volume_ratio', 1)\n    # 股票类交易手续费是：买入时佣金万分之三，卖出时佣金万分之三加千分之一印花税, 每笔交易佣金最低扣5块钱\n    set_order_cost(OrderCost(open_tax=0, close_tax=0.001, \\\n                             open_commission=0.0003, close_commission=0.0003,\\\n                             close_today_commission=0, min_commission=5), type='stock')\n    # 持仓数量\n    g.stocknum = 10\n    # 交易日计时器\n    g.days = 0 \n    # 调仓频率\n    g.refresh_rate = 40\n    # 运行函数\n    run_daily(trade, 'every_bar')\n\n## 选出小市值股票\ndef check_stocks(context,date):\n    # 设定查询条件\n    q = query(\n                valuation.code,\n                valuation.pb_ratio,\n                valuation.pe_ratio\n            ).filter(\n                valuation.pb_ratio<0,\n                valuation.pe_ratio<0\n            ).order_by(\n                valuation.pe_ratio*valuation.pb_ratio\n            )\n    # 选出负市盈率负市净率的股票，构成buylist\n    df = get_fundamentals(q)\n    buylist =list(df['code'])\n\n    # 过滤停牌股票\n    buylist = filter_paused_stock(buylist)\n\n    return buylist[:g.stocknum]\n  \n## 交易函数\ndef trade(context):\n    if g.days%g.refresh_rate == 0:\n\n        ## 获取持仓列表\n        sell_list = list(context.portfolio.positions.keys())\n        # 如果有持仓，则卖出\n        if len(sell_list) > 0 :\n            for stock in sell_list:\n                order_target_value(stock, 0)\n\n        ## 分配资金\n        if len(context.portfolio.positions) < g.stocknum :\n            Num = g.stocknum - len(context.portfolio.positions)\n            Cash = context.portfolio.cash/Num\n        else: \n            Cash = 0\n\n        ## 选股\n        date = context.current_dt.year\n        stock_list = check_stocks(context,date)\n\n        ## 买入股票\n        for stock in stock_list:\n            if len(context.portfolio.positions.keys()) < g.stocknum:\n                order_value(stock, Cash)\n\n        # 天计数加一\n        g.days = 1\n    else:\n        g.days += 1\n\n# 过滤停牌股票\ndef filter_paused_stock(stock_list):\n    current_data = get_current_data()\n    return [stock for stock in stock_list if not current_data[stock].paused]"
