  "code": "from __future__ import print_function, division\nimport pandas as pd\n\nfrom jqdata import *\npd.set_option('display.max_rows', None)\npd.set_option('display.max_columns', None)\npd.set_option('display.width', None)\npd.set_option('display.max_colwidth', -1)\n\ntoday = '2022-04-29'\n\n\ndateRangeList=get_trade_days(start_date='2022-03-15',end_date='2022-04-29')\nx=0\nfor i in dateRangeList:\n    x=x+1\n    \n    #today = datetime.datetime.today().strftime(\"%Y-%m-%d\")\n    today = i.strftime(\"%Y-%m-%d\")\n    # 获取行业列表\n    #print(\"使用申万二级行业\")\n    industries_pd = get_industries(name='sw_l2')\n\n    INDUSTRY_CODE_NAME_DICT = {}\n    for index in industries_pd.index:\n        INDUSTRY_CODE_NAME_DICT[index] = industries_pd.loc[index]['name'][:-2]\n\n    # 获取行业成份股\n    industry_code_count_dict = {}\n    for industry_code in industries_pd.index:\n        stocks = get_industry_stocks(industry_code)\n        industry_code_count_dict[industry_code] = len(stocks)\n\n    security_industry_dict = {}\n    for industry_code in industries_pd.index:\n        stocks = get_industry_stocks(industry_code)\n        for security_code in stocks:\n            security_industry_dict[security_code] = industry_code\n\n    #print(\"过滤掉退市股、上市未满 150 天的新股\")\n    # 获取所有标的信息\n    all_securities_pd = get_all_securities()\n\n    # 过滤掉退市股\n    filtered_securities_pd = all_securities_pd[all_securities_pd.end_date>datetime.date.today()]\n\n    # 过滤掉最近 150 天上市的新股\n    last_150_days = datetime.date.today() - datetime.timedelta(days=150)\n    filtered_securities_pd = filtered_securities_pd[filtered_securities_pd.start_date<last_150_days]\n\n    security_code_list = filtered_securities_pd.index.tolist()\n\n    #获取一支或者多只标的的行情数据\n    date_security_close_money_pd = get_price(security_code_list, start_date=None, end_date=today, frequency='daily', fields=['close', 'money'], skip_paused=False, fq='pre', count=25, panel=False)\n\n    security_date_close_money_dict = {}\n    for row in date_security_close_money_pd.itertuples():\n\n        security_code = row.code\n\n        date = row.time.strftime(\"%Y-%m-%d\")\n        close = row.close\n        money = row.money\n\n        info = [date, close, money]\n\n        if security_code not in security_date_close_money_dict:\n            security_date_close_money_dict[security_code] = [info]\n        else:\n            security_date_close_money_dict[security_code].append(info)\n\n    ###########\n    #print(\"按 20 日涨幅排序，统计涨幅超过 20% 的前排个股\")\n    all_result = []\n\n    # for day in [-1, -2, -3, -4, -5]:   \n    # print(day+6)\n\n    day = -1\n    security_growth = {}\n    for security_code, date_close_money_list in security_date_close_money_dict.items():\n        date = date_close_money_list[day][0]\n        growth = (date_close_money_list[day][1]-date_close_money_list[day-20][1])/date_close_money_list[day-20][1]\n        security_growth[security_code] = growth\n\n    sorted_security_growth =sorted(security_growth.items(), key=lambda t: t[1], reverse=True)\n\n\n    index = []\n    data = {}\n    data[\"twenty_day_growth\"] = []\n\n    for item in sorted_security_growth:\n\n        security_code = item[0]\n        growth = item[1]\n\n        index.append(security_code)\n        data[\"twenty_day_growth\"].append(growth)\n\n    sorted_security_growth_pd = pd.DataFrame(data, index=index)\n    top_security_growth_pd = sorted_security_growth_pd[sorted_security_growth_pd.twenty_day_growth>0.2]\n\n    front_industry_count_dict = {}\n    for security_code in top_security_growth_pd.index.tolist():\n        industry_code = security_industry_dict.get(security_code)\n        if industry_code:\n            if industry_code not in front_industry_count_dict:\n                front_industry_count_dict[industry_code] = 1\n            else:\n                front_industry_count_dict[industry_code] += 1\n\n    # 计算动量 （momentum）\n    industry_code_result = {}\n    for industry_code, count in front_industry_count_dict.items():\n        industry_code_result[industry_code] = float(format(count * count / industry_code_count_dict[industry_code], '.2f'))\n\n    sorted_industry_code_result = sorted(industry_code_result.items(), key = lambda kv:(kv[1], kv[0]), reverse=True)[:15]\n\n    # 行业代码转换为行业名称\n    index = []\n    data = []\n    for item in sorted_industry_code_result:\n\n        industry_code = item[0]\n        if not industry_code:\n            continue\n\n        data.append(\"{}({})\".format(INDUSTRY_CODE_NAME_DICT[industry_code], item[1]))\n        #data.append(item[1])\n    df = pd.DataFrame(data, columns=[\"{}动量得分\".format(date[5:])])\n   # df = pd.DataFrame(data, index=index, columns=[\"{}动量得分\".format(date[5:])])\n    #df = df.reset_index(drop = False)\n\n    #df = df .rename(columns={'index':'行业'})\n    if x==1:\n        df1 = df\n    else:\n        df1=pd.concat([df, df1], axis=1)\n    print(today,\"计算完成|\", end=' ')\n\ndf1=df1.T\ndf1\n\n# ─── 代码块 2 ───\n\nwrite_file('动量行业.csv',df1.to_csv(encoding=\"utf-8-sig\"), append=False) "
